function replaceOnce(s,a,b,label){const n=count(s,a);if(n!==1)fail('patch_anchor_mismatch:'+label+':'+n);return s.replace(a,b)}
function patchBase(s){const a="  imotion_marketing_targets_register_v2: { operation: 'host_action.imotion_marketing_targets_register_v2', rollback: 'host-action-v2:imotion-marketing-targets-register-v2:source-restore' },\n  drtarjomeh_security_containment_v1:";const b="  imotion_marketing_targets_register_v2: { operation: 'host_action.imotion_marketing_targets_register_v2', rollback: 'host-action-v2:imotion-marketing-targets-register-v2:source-restore' },\n  deployhq_node1_canonical_recreate_v1: { operation: 'host_action.deployhq_node1_canonical_recreate_v1', rollback: 'host-action-v2:deployhq-node1-canonical-recreate-v1:adapter-rollback' },\n  drtarjomeh_security_containment_v1:";return replaceOnce(s,a,b,'base_registry')}
function patchExecutor(s){const a="  imotion_marketing_targets_register_v2:{operation:'host_action.imotion_marketing_targets_register_v2',kind:'imotion_marketing_targets_register_v2'},\n  drtarjomeh_security_containment_v1:";const b="  imotion_marketing_targets_register_v2:{operation:'host_action.imotion_marketing_targets_register_v2',kind:'imotion_marketing_targets_register_v2'},\n  deployhq_node1_canonical_recreate_v1:{operation:'host_action.deployhq_node1_canonical_recreate_v1',kind:'deployhq_node1_canonical_recreate_v1'},\n  drtarjomeh_security_containment_v1:";s=replaceOnce(s,a,b,'executor_registry');const anchor="const applyHostActionV2Original=applyHostActionV2;\n";const code=`const DEPLOYHQ_NODE1_HELPER='${PATHS.helper}';\nconst DEPLOYHQ_NODE1_RESULT='${PATHS.result}';\nfunction applyDeployHQNode1CanonicalRecreateV1(){if(!fs.existsSync(DEPLOYHQ_NODE1_HELPER))throw new Error('deployhq_node1_helper_missing');fs.mkdirSync(path.dirname(DEPLOYHQ_NODE1_RESULT),{recursive:true,mode:0o700});try{fs.unlinkSync(DEPLOYHQ_NODE1_RESULT)}catch(e){if(e.code!=='ENOENT')throw e}const u='prhm-deployhq-node1-recreate-'+Date.now();const args=['--wait','--quiet','--unit='+u,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=strict','--property=ProtectHome=true','--property=RestrictAddressFamilies=AF_INET AF_UNIX','--property=ReadWritePaths=/var/lib/prhm-agent-selfmaint-exec/deployhq-node1-canonical-recreate-v1','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',DEPLOYHQ_NODE1_HELPER];cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:120000});const r=readJson(DEPLOYHQ_NODE1_RESULT);if(r.ok!==true||r.action!=='deployhq_node1_canonical_recreate_v1'||r.schema_version!=='prhm.host-action-result.v1'||typeof r.canonical_created!=='boolean'||!r.canonical_identifier||r.config_match!==true||r.deployment_executed!==false||r.command_executed!==false||r.honartik_targets_mutated!==false||r.rollback_performed!==false||r.database_mutation!==false)throw new Error('deployhq_node1_result_invalid');return r}\n`;s=replaceOnce(s,anchor,code+anchor,'executor_helper');const d="if(action==='imotion_marketing_targets_register_v2')return applyImotionMarketingTargetsRegisterV2();";s=replaceOnce(s,d,"if(action==='deployhq_node1_canonical_recreate_v1')return applyDeployHQNode1CanonicalRecreateV1();"+d,'executor_dispatch');return s}
function patchPolicy(s){const d=JSON.parse(s);if(!d.operations||!Array.isArray(d.typed_scopes))fail('policy_shape_invalid');if(d.operations[OPERATION]||d.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_target_already_exists');d.operations[OPERATION]={level:4};d.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});return JSON.stringify(d,null,2)+'\n'}
function patchMcp(s){const a="'imotion_marketing_targets_register_v2','drtarjomeh_security_containment_v1'";const b="'imotion_marketing_targets_register_v2','deployhq_node1_canonical_recreate_v1','drtarjomeh_security_containment_v1'";return replaceOnce(s,a,b,'mcp_enum')}
function patchZdt(s,h){s=replaceOnce(s,BASELINE.mcp,h.mcp,'zdt_mcp');s=replaceOnce(s,BASELINE.base,h.base,'zdt_base');s=replaceOnce(s,BASELINE.executor,h.executor,'zdt_executor');return s}
function helperTemplate(){const b=Buffer.from(HELPER_TEMPLATE_B64,'base64');if(sha(b)!==HELPER_TEMPLATE_SHA)fail('helper_template_sha_mismatch');return b}
function regular(f){const st=fs.lstatSync(f);return st.isFile()&&!st.isSymbolicLink()}
function verifyBaseline(){for(const k of ['base','executor','policy','mcp','zdt']){if(!fs.existsSync(PATHS[k])||!regular(PATHS[k]))fail('missing_or_unsafe:'+k);const a=shaFile(PATHS[k]);if(a!==BASELINE[k])fail('baseline_drift:'+k+':'+a)}if(fs.existsSync(PATHS.helper))fail('helper_target_already_exists');return true}
function syntax(bytes,ext,label){const f='/tmp/prhm-deployhq-node1-reg-'+label+'-'+process.pid+ext;try{fs.writeFileSync(f,bytes,{flag:'wx',mode:0o600});const r=cp.spawnSync('/usr/local/bin/prhm-node',['--check',f],{encoding:'utf8',timeout:30000,maxBuffer:200000});if(r.error||r.status!==0)fail('syntax_failed:'+label+':'+String(r.stderr||r.stdout||r.error?.message||'').slice(-500))}finally{try{fs.unlinkSync(f)}catch{}}}
function build(){verifyBaseline();const base=Buffer.from(patchBase(fs.readFileSync(PATHS.base,'utf8'))),executor=Buffer.from(patchExecutor(fs.readFileSync(PATHS.executor,'utf8'))),policy=Buffer.from(patchPolicy(fs.readFileSync(PATHS.policy,'utf8'))),mcp=Buffer.from(patchMcp(fs.readFileSync(PATHS.mcp,'utf8')));const hashes={base:sha(base),executor:sha(executor),policy:sha(policy),mcp:sha(mcp)};const zdt=Buffer.from(patchZdt(fs.readFileSync(PATHS.zdt,'utf8'),hashes));hashes.zdt=sha(zdt);const helper=helperTemplate();hashes.helper=sha(helper);syntax(base,'.cjs','base');syntax(executor,'.cjs','executor');syntax(mcp,'.mjs','mcp');syntax(zdt,'.cjs','zdt');syntax(helper,'.cjs','helper');JSON.parse(policy.toString());return{base,executor,policy,mcp,zdt,helper,hashes}}
function atomic(f,b,mode){fs.mkdirSync(path.dirname(f),{recursive:true,mode:0o755});const t=f+'.tmp-'+process.pid+'-'+Date.now();let fd;try{fd=fs.openSync(t,'wx',mode);fs.writeFileSync(fd,b);fs.fsyncSync(fd)}finally{if(fd!==undefined)fs.closeSync(fd)}fs.renameSync(t,f);fs.chmodSync(f,mode)}
function backupOriginals(){const dir=path.join(BACKUP_ROOT,new Date().toISOString().replace(/[:.]/g,'-'));fs.mkdirSync(dir,{recursive:true,mode:0o700});const states={};for(const k of ['base','executor','policy','mcp','zdt']){const f=PATHS[k],st=fs.lstatSync(f),bak=path.join(dir,k+'.bak');fs.copyFileSync(f,bak,fs.constants.COPYFILE_EXCL);fs.chmodSync(bak,0o600);states[k]={file:f,backup:bak,mode:st.mode&0o777,sha256:shaFile(f)}}return{dir,states}}
function restoreBackup(b,mutated){const errors=[];for(const k of [...mutated].reverse()){try{if(k==='helper'){try{fs.unlinkSync(PATHS.helper)}catch(e){if(e.code!=='ENOENT')throw e};continue}const st=b.states[k],bytes=fs.readFileSync(st.backup);if(sha(bytes)!==st.sha256)throw new Error('backup_sha_mismatch');atomic(st.file,bytes,st.mode)}catch(e){errors.push(k+':'+e.message)}}if(errors.length)fail('rollback_restore_failed:'+errors.join('|'));return true}
function restartServices(){for(const u of ['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service']){cp.execFileSync('/usr/bin/systemctl',['restart',u],{stdio:['ignore','pipe','pipe'],timeout:90000});const a=cp.execFileSync('/usr/bin/systemctl',['is-active',u],{encoding:'utf8',timeout:30000}).trim();if(a!=='active')fail('service_not_active:'+u)}}
function resultBase(){return{ok:false,action:INSTALLER_ACTION,target_action:ACTION,schema_version:'prhm.host-action-bootstrap-result.v1',production_site_mutation:false,database_mutation:false,deployhq_mutation:false,mcp_refresh_required:true,rollback:{performed:false}}}
function preflight(){const c=build();return{...resultBase(),ok:true,preflight_only:true,production_mutation:false,baseline_match:true,candidate_sha256:c.hashes,helper_template_sha256:HELPER_TEMPLATE_SHA,rollback:{performed:false}}}
function apply(){const out=resultBase(),c=build(),backup=backupOriginals(),mutated=[];try{for(const k of ['helper','base','executor','policy','mcp','zdt']){mutated.push(k);atomic(PATHS[k],c[k],k==='helper'?0o750:backup.states[k].mode);if(shaFile(PATHS[k])!==c.hashes[k])fail('post_write_sha_mismatch:'+k)}restartServices();Object.assign(out,{ok:true,installed:true,preflight_only:false,production_mutation:true,deployhq_mutation:false,backup_dir:backup.dir,post_install_sha256:c.hashes});fs.mkdirSync(path.dirname(REG_RESULT),{recursive:true,mode:0o700});atomic(REG_RESULT,Buffer.from(JSON.stringify(out,null,2)+'\n'),0o600);return out}catch(e){let rb=false;try{restoreBackup(backup,mutated);restartServices();rb=true}catch(rbe){throw new Error('install_failed_and_rollback_failed:'+e.message+':'+rbe.message)}throw new Error('install_failed_rolled_back:'+e.message+':rollback='+rb)}}
function main(){const a=process.argv.slice(2);if(a.length!==1||!['--preflight-only','--apply'].includes(a[0]))fail('unexpected_arguments');process.stdout.write(JSON.stringify(a[0]==='--preflight-only'?preflight():apply())+'\n')}
if(require.main===module){try{main()}catch(e){console.error(JSON.stringify({ok:false,error:e.message}));process.exit(1)}}
